svg.script:

(function() {
	"use strict";

	// ========== CALCULATE LUMINANCE ==========
	function getLuminance(hexColor) {
		const hex = hexColor.replace('#', '');
		const r = parseInt(hex.substr(0, 2), 16) / 255;
		const g = parseInt(hex.substr(2, 2), 16) / 255;
		const b = parseInt(hex.substr(4, 2), 16) / 255;

		// Standard luminance formula
		const luminance = (0.299 * r + 0.587 * g + 0.114 * b);
		return luminance;
	}

	// ========== GRADIENT COLOR GENERATION ==========
	function generateGradientColors(centerColor) {
		const hex = centerColor.replace('#', '');
		const r = parseInt(hex.substr(0, 2), 16);
		const g = parseInt(hex.substr(2, 2), 16);
		const b = parseInt(hex.substr(4, 2), 16);

		const rn = r / 255, gn = g / 255, bn = b / 255;
		const max = Math.max(rn, gn, bn), min = Math.min(rn, gn, bn);
		let h, s, l = (max + min) / 2;

		if (max === min) {
			h = s = 0;
		} else {
			const d = max - min;
			s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
			switch (max) {
				case rn: h = (gn - bn) / d + (gn < bn ? 6 : 0); break;
				case gn: h = (bn - rn) / d + 2; break;
				case bn: h = (rn - gn) / d + 4; break;
			}
			h /= 6;
		}

		const hslToHex = (hh, ss, ll) => {
			const c = (1 - Math.abs(2 * ll - 1)) * ss;
			const x = c * (1 - Math.abs((hh * 6) % 2 - 1));
			const mm = ll - c / 2;
			let rr = 0, gg = 0, bb = 0;

			if (hh < 1/6) [rr, gg, bb] = [c, x, 0];
			else if (hh < 2/6) [rr, gg, bb] = [x, c, 0];
			else if (hh < 3/6) [rr, gg, bb] = [0, c, x];
			else if (hh < 4/6) [rr, gg, bb] = [0, x, c];
			else if (hh < 5/6) [rr, gg, bb] = [x, 0, c];
			else [rr, gg, bb] = [c, 0, x];

			const toHex = (val) => Math.round((val + mm) * 255).toString(16).padStart(2, '0');
			return `#${toHex(rr)}${toHex(gg)}${toHex(bb)}`;
		};

		return {
			light: hslToHex(h, s, Math.min(l + 0.12, 0.95)),
			center: centerColor,
			dark: hslToHex(h, s, Math.max(l - 0.08, 0.15))
		};
	}

	function updateGradient(centerColorParam) {
		const colors = generateGradientColors(centerColorParam);
		const gradient = document.getElementById('banner-pink');
		const stops = gradient.querySelectorAll('stop');

		stops[0].setAttribute('stop-color', colors.light);
		stops[1].setAttribute('stop-color', colors.center);
		stops[2].setAttribute('stop-color', colors.dark);

		// Update text color based on background luminance
		const luminance = getLuminance(colors.center);
		const textElement = document.getElementById('streamer-text');
		if (textElement) {
			textElement.setAttribute('fill', luminance > 0.5 ? '#2d124d' : '#ffffff');
		}
	}

	// ========== BANNER INITIALIZATION ==========
	function initializeBanner() {
		try {
			const urlParams = new URLSearchParams(window.location.search);
			console.log('Banner initialization started');

			// Update gradient color from ?color=#ffd3ed
			const colorParam = urlParams.get('color');
			console.log('Color param:', colorParam);
			if (colorParam && /^#[0-9A-Fa-f]{6}$/i.test(colorParam)) {
				console.log('Applying color:', colorParam);
				updateGradient(colorParam);
			}

			// Update avatar image from ?image=<url>
			const imageUrl = urlParams.get('image');
			console.log('Image URL:', imageUrl);
			const avatarElement = document.getElementById('dynamic-avatar');
			if (avatarElement) {
				if (imageUrl && isValidUrl(imageUrl)) {
					console.log('Setting image href to:', imageUrl);
					avatarElement.setAttribute('href', imageUrl);
				}
			}

			// Update banner text from ?text=<text>
			const textParam = urlParams.get('text');
			console.log('Text param:', textParam);
			if (textParam) {
				const textElement = document.getElementById('streamer-text');
				if (textElement) {
					const decodedText = decodeURIComponent(textParam).trim();
					if (decodedText.length > 0 && decodedText.length < 100) {
						// Clear existing text nodes
						while (textElement.firstChild) {
							textElement.removeChild(textElement.firstChild);
						}
						// Add new text node
						textElement.appendChild(document.createTextNode(decodedText));
						console.log('Text updated to:', decodedText);
					}
				}
			}
		} catch (error) {
			console.warn('Banner initialization error:', error);
		}
	}

	function isValidUrl(string) {
		try {
			// Accept both full URLs and local file paths
			if (string.startsWith('http://') || string.startsWith('https://')) {
				new URL(string);
				return true;
			}
			// Accept local file paths (e.g., image.png, images/photo.jpg)
			if (string.includes('.')) {
				return true;
			}
			return false;
		} catch (_) {
			return false;
		}
	}

	// Initialize when DOM is ready
	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', initializeBanner);
	} else {
		initializeBanner();
	}
})();
